reference_solution:
def smallest_cyclic_edit_string(s,k):
    output=[]
    for char in s:
        chosen=char
        for code in range(ord('a'),ord(char)+1):
            distance=min(ord(char)-code,26-ord(char)+code)
            if distance<=k:chosen=chr(code);k-=distance;break
        output.append(chosen)
    return ''.join(output)

